-- Run after applying migrations/20260924030000_ledger_cents.sql. Read-only.
-- Every row must say ok = true: the database splits money exactly as the web
-- and iOS apps do. Expected values come from src/lib/ledger.ts
-- (tests/ledger-vectors.json plus one hand-built flat with a duplicate
-- participant, an empty split and a CHF expense).
select 'fnv1a' as check_name, s as input, public.fnv1a(s) = want as ok
from (values
  ('', 2166136261),
  ('a', 3826002220),
